import attr

from .connection_details import IperfDataTransferDetails
from typing import Optional, List


@attr.s(cmp=False)
class AppServer(object):
    """

    :param iperf_details: represents the iperf details in the App server
    """
    iperf_details = attr.ib(type=IperfDataTransferDetails)


@attr.s(cmp=False)
class AppServerAndroid(object):
    """
    :param str app_server_name: name of the app_server e.g. APP1
    :param str host: Application Server IP
    :param user: Application Server SSH login
    :param password: Application Server SSH password
    :param Optional[str] iperf_interface_ip: OPTIONAL Application Server interface used to bind IP (-B iperf parameter)
    """
    app_server_name = attr.ib(type=str)
    host = attr.ib(type=str)
    user = attr.ib(type=str)
    password = attr.ib(type=str)
    iperf_interface_ip = attr.ib(type=Optional[str])


@attr.s(cmp=False)
class TafUeAppServer(object):
    """
    More information about TafUeAppServer model can be found at the following links:
    __init__.py: https://confluence.ext.net.nokia.com/display/AbstractLibs/taf.ue%3A+__init__.py+configuration+file
    yaml: https://confluence.ext.net.nokia.com/display/AbstractLibs/ute_ue%3A+YAML+configuration+file

    :param str app_server_name: MANDATORY application server name, e.g.: APP_1
    :param str address: MANDATORY application server address
    :param str user: MANDATORY application server username
    :param str password: MANDATORY application server password
    :param Optional[str] bind_interface_ip: OPTIONAL IP of the application server interface to bind iperf server to IP
                                            different than host IP
                                             * Used for LTE data transfer.
                                             * This is iperf "-B" option.
                                             * Used only during UPLINK data transfer when server is established on app
                                               server.
                                             At  DOWNLINK server always binds to UE IP.
    :param Optional[str] expected_prompt: MANDATORY for taf.ue.at and taf.ue.iphone, OPTIONAL for other plugins
                                          regex that should match prompt on App Server
    :param Optional[str] binary_path: OPTIONAL binary path of the application server iperf tool
                                            to use alternative iperf tool like '/home/cmw_sg4/NAA/iperf'
                                            rather than default iperf tool '/usr/bin/iperf'
                                            * Used for LTE data transfer.
    :param Optional[List[int] ports: OPTIONAL ports which are allowed to use

    """
    app_server_name = attr.ib(type=str)
    address = attr.ib(type=str)
    user = attr.ib(type=str)
    password = attr.ib(type=str)
    bind_interface_ip = attr.ib(type=Optional[str], default=None)
    expected_prompt = attr.ib(type=Optional[str], default=None)
    binary_path = attr.ib(type=Optional[str], default=None)
    ports = attr.ib(type=Optional[List[int]], default=None)
